<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Resumen financiero — Hache Natación</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f6fa;font-family:Arial,sans-serif;color:#172033}.wrap{max-width:980px;margin:auto;padding:72px 14px 36px}h1{margin:0 0 5px;font-size:28px}.sub{color:#64748b;font-size:13px;margin-bottom:16px}.periodo{width:100%;padding:12px;border:1px solid #cbd5e1;border-radius:12px;background:#fff;font-size:16px;margin-bottom:14px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.card{background:#fff;border-radius:16px;padding:14px;box-shadow:0 3px 12px #0000000d}.card.big{grid-column:1/-1}.k{font-size:11px;color:#64748b;text-transform:uppercase;font-weight:800;letter-spacing:.05em}.v{font-size:25px;font-weight:900;margin-top:5px}.s{font-size:12px;color:#64748b;margin-top:5px}.section{margin-top:18px}.section h2{font-size:18px;margin:0 0 10px}.row{display:flex;justify-content:space-between;gap:12px;padding:11px 0;border-bottom:1px solid #eef2f7}.row:last-child{border-bottom:0}.row strong{font-size:14px}.row span{font-size:13px;color:#64748b}.empty{padding:20px;text-align:center;color:#64748b}.error{color:#991b1b;font-weight:700}.bar{height:8px;background:#e2e8f0;border-radius:99px;overflow:hidden;margin-top:7px}.fill{height:100%;background:#172033}@media(min-width:720px){.wrap{padding-top:36px}.grid{grid-template-columns:repeat(4,1fr)}.card.big{grid-column:span 2}}
</style></head><body><main class="wrap"><h1>Resumen financiero</h1><div class="sub">Cobertura mensual e ingresos realmente recibidos</div><input id="periodo" class="periodo" type="month"><div id="contenido"><div class="empty">Cargando…</div></div></main><script>
const p=document.getElementById('periodo'),c=document.getElementById('contenido');const d=new Date();p.value=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');p.onchange=cargar;const money=n=>Number(n||0).toLocaleString('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0});
function card(k,v,s='',big=false){return `<div class="card ${big?'big':''}"><div class="k">${k}</div><div class="v">${v}</div>${s?`<div class="s">${s}</div>`:''}</div>`}
async function cargar(){c.innerHTML='<div class="empty">Cargando…</div>';try{const [anio,mes]=p.value.split('-').map(Number),r=await fetch(`/api/resumen-financiero.php?mes=${mes}&anio=${anio}`),x=await r.json();if(!r.ok||!x.ok)throw new Error(x.error||'No se pudo cargar');const t=x.por_tipo,m=x.mensualidades_periodo;const max=Math.max(1,...x.metodos.map(v=>Number(v.total||0)));c.innerHTML=`<div class="grid">${card('Mensualidades del periodo',m.alumnos,money(m.total)+' cubiertos',true)}${card('Dinero recibido',money(x.caja.total),x.caja.cantidad+' pagos')}${card('Alumnos con pagos',x.caja.alumnos)}${card('Inscripciones',money(t.INSCRIPCION.total),t.INSCRIPCION.cantidad+' pagos')}${card('Mensualidades cobradas',money(t.MENSUALIDAD.total),t.MENSUALIDAD.cantidad+' pagos')}${card('Cursos intensivos',money(t.INTENSIVO.total),t.INTENSIVO.cantidad+' pagos')}</div><section class="section"><h2>Métodos de pago</h2><div class="card">${x.metodos.length?x.metodos.map(v=>`<div class="row"><div><strong>${v.metodo.replace('_',' ')}</strong><div class="bar"><div class="fill" style="width:${Math.max(4,Number(v.total)/max*100)}%"></div></div></div><span>${money(v.total)} · ${v.cantidad}</span></div>`).join(''):'<div class="empty">Sin movimientos.</div>'}</div></section>`;}catch(e){c.innerHTML='<div class="empty error">'+e.message+'</div>'}}cargar();
</script></body></html>